package com.edward.galleryflow;
import android.content.Context;import android.graphics.*;import android.widget.TextView;
/** Small monochrome outline actions, matching the floating toolbar. */
final class ActionIcon extends TextView{
 final String label;final Paint p=new Paint(3);
 ActionIcon(Context c,String label){super(c);this.label=label.toLowerCase(java.util.Locale.ROOT);}
 protected void onDraw(Canvas c){String k=label;boolean grid=k.startsWith("interface"),viewer=k.equals("media viewer"),refresh=k.equals("refresh"),undo=k.startsWith("undo"),access=k.startsWith("allow media"),close=k.startsWith("close"),back=k.startsWith("back"),play=k.contains("slideshow")||k.startsWith("play")||k.startsWith("pause"),lock=k.contains("lock")||k.contains("admin"),remove=k.startsWith("remove from"),settings=k.startsWith("settings")||k.equals("main"),arrow=k.startsWith("first image")||k.startsWith("last image")||k.startsWith("previous")||k.startsWith("next"),share=k.startsWith("share"),copy=k.startsWith("copy"),heart=k.contains("favorite"),edit=k.startsWith("edit"),trash=k.startsWith("delete")||k.contains("trash"),sort=k.startsWith("sort"),info=k.contains("information")||k.equals("about");if(!grid&&!viewer&&!refresh&&!undo&&!access&&!close&&!back&&!play&&!lock&&!remove&&!settings&&!arrow&&!share&&!copy&&!heart&&!edit&&!trash&&!sort&&!info){super.onDraw(c);return;}c.save();float size=24*getResources().getDisplayMetrics().density;c.translate((getWidth()-size)/2,(getHeight()-size)/2);c.scale(size/24,size/24);p.setColor(getCurrentTextColor());p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.7f);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);
 if(close){c.drawLine(6,6,18,18,p);c.drawLine(6,18,18,6,p);}else if(grid){for(int x=4;x<=14;x+=10)for(int y=4;y<=14;y+=10)c.drawRect(x,y,x+6,y+6,p);}else if(viewer){c.drawRect(3,4,21,20,p);c.drawLine(4,18,10,10,p);c.drawLine(10,10,15,16,p);c.drawLine(15,16,18,12,p);c.drawCircle(17,8,1,p);}else if(refresh||undo){c.drawArc(4,4,20,20,45,280,false,p);c.drawLine(4,4,4,10,p);c.drawLine(4,10,10,10,p);}else if(access){c.drawLine(4,13,10,19,p);c.drawLine(10,19,20,5,p);}else if(back){c.drawLine(4,12,20,12,p);c.drawLine(4,12,11,5,p);c.drawLine(4,12,11,19,p);}else if(lock){c.drawRoundRect(5,10,19,21,2,2,p);c.drawArc(7,2,17,15,180,k.startsWith("unlock")?230:180,false,p);c.drawLine(12,14,12,17,p);}else if(remove){c.drawLine(5,12,19,12,p);}else if(settings){c.drawCircle(12,12,6,p);c.drawCircle(12,12,2,p);for(int n=0;n<8;n++){c.save();c.rotate(n*45,12,12);c.drawLine(12,3,12,5,p);c.restore();}}else if(play){boolean paused=getText().toString().contains("Ⅱ");if(paused){c.drawLine(9,5,9,19,p);c.drawLine(15,5,15,19,p);}else{Path t=new Path();t.moveTo(7,4);t.lineTo(20,12);t.lineTo(7,20);t.close();c.drawPath(t,p);}}else if(arrow){boolean prev=k.startsWith("previous")||k.startsWith("first");c.save();if(k.contains("month"))c.rotate(prev?90:-90,12,12);else if(!prev)c.rotate(180,12,12);c.drawLine(7,12,16,5,p);c.drawLine(7,12,16,19,p);if(k.startsWith("first")||k.startsWith("last"))c.drawLine(4,5,4,19,p);c.restore();}else if(sort){c.drawLine(4,6,20,6,p);c.drawLine(4,12,15,12,p);c.drawLine(4,18,10,18,p);}else if(info){c.drawCircle(12,12,9,p);c.drawLine(12,11,12,17,p);c.drawPoint(12,7,p);}else if(share){c.drawLine(7,11,17,6,p);c.drawLine(7,13,17,18,p);c.drawCircle(5,12,2,p);c.drawCircle(19,5,2,p);c.drawCircle(19,19,2,p);}else if(copy){c.drawRoundRect(8,6,20,21,2,2,p);Path a=new Path();a.moveTo(15,3);a.lineTo(4,3);a.lineTo(4,17);c.drawPath(a,p);}else if(heart){Path a=new Path();a.moveTo(12,21);a.cubicTo(-5,10,4,-1,12,7);a.cubicTo(20,-1,29,10,12,21);c.drawPath(a,p);}else if(trash){c.drawLine(4,6,20,6,p);c.drawLine(9,3,15,3,p);c.drawRoundRect(6,6,18,21,1,1,p);c.drawLine(10,10,10,17,p);c.drawLine(14,10,14,17,p);}else{Path a=new Path();a.moveTo(4,20);a.lineTo(5,15);a.lineTo(17,3);a.lineTo(21,7);a.lineTo(9,19);a.close();c.drawPath(a,p);c.drawLine(14,6,18,10,p);}c.restore();}
}
